const name = "Maria";   // text never changes, so const
let age = 18;            // this will change, so let
age = age + 1;
const isStudent = true;

console.log(name);
console.log(age);
console.log(isStudent);

const hour = 14;

if (hour < 12) {
  console.log("Good morning");
} else if (hour < 18) {
  console.log("Good afternoon");
} else {
  console.log("Good evening");
}

